export type PolicyBlock = { type: "p" | "h2" | "h3" | "li"; text: string };
export type Policy = { slug: string; title: string; updated: string; blocks: PolicyBlock[] };

export const policies: Policy[] = [ { "slug": "purchase", "title": "Purchase Policy", "updated": "August 2, 2026", "blocks": [ { "type": "p", "text": "Our goal is to make your purchasing experience easy, efficient, and equitable, so we can get you on your way to live events as quickly as possible. The following is designed to ensure your satisfaction and understanding of the purchase process on the Blocktickets sites (collectively, the “Site”). If you have any questions, please contact help@blocktickets.xyz. Your purchases on our Site are subject to these terms. Please also review our Terms & Conditions, which govern your use of our Site." }, { "type": "h2", "text": "Currency" }, { "type": "p", "text": "All ticket prices for events that occur in the United States are stated in U.S. Dollars. All ticket prices for events that occur in Canada are stated in Canadian Dollars." }, { "type": "h2", "text": "Payment Methods" }, { "type": "p", "text": "We accept several methods of payment to accommodate your needs. If the event for which you are buying tickets is located in the United States, Blocktickets accepts American Express, Visa, Mastercard, and Discover. If the event for which you are buying tickets is located in Canada, Blocktickets accepts American Express, Visa, and Mastercard." }, { "type": "h2", "text": "Who You Are Buying From" }, { "type": "p", "text": "Blocktickets is a self-service online ticketing and event marketing application. Blocktickets acts as the agent of those who are promoting or otherwise providing the events for which you purchase tickets, such as museums, venues, teams, artist representatives and fan clubs, promoters, and leagues (collectively, “Event Providers”). When you purchase a ticket through the Site, Blocktickets Technologies, Inc. handles the transaction and collects payment for the Event Provider." }, { "type": "p", "text": "Tickets obtained from unauthorized sources may be lost, stolen, or counterfeit, and if so are void." }, { "type": "h2", "text": "Pricing and Availability" }, { "type": "p", "text": "We sell tickets on behalf of Event Providers, which means we do not set ticket prices or determine seating locations or ticket availability. Seating charts reflect the general layout of the venue at this time. For some events, the layout and specific seat locations may vary without notice. Tickets are generally sold through several distribution points, including online, phone centers, and box offices. Most distribution points generally access the same ticketing system and inventory; therefore, tickets for popular events may sell out quickly. Occasionally, additional tickets may become available prior to the event. However, we do not control this inventory or its availability." }, { "type": "h2", "text": "Order Confirmation" }, { "type": "p", "text": "If you do not receive a confirmation number (in the form of a confirmation page or email) after submitting payment information, or if you experience an error message or service interruption after submitting payment information, it is your responsibility to confirm via your account or Blocktickets customer service whether or not your order has been placed. Only you may be aware of any problems that occur during the purchase process. We will not be responsible for losses (monetary or otherwise) if you assume that an order was not placed because you failed to receive confirmation." }, { "type": "h2", "text": "Number of Tickets (“Ticket Limits”)" }, { "type": "p", "text": "When purchasing tickets on our Site, you are limited to a specified number of tickets for each event (also known as a “ticket limit”). This ticket limit is posted during the purchase process and is verified with every transaction. This policy is in effect to discourage unfair ticket-buying practices. We reserve the right to cancel any or all orders and tickets without notice to you if you exceed the posted limits. This includes orders associated with the same name, email address, billing address, credit card number, or other information." }, { "type": "h2", "text": "Opening Acts / Festival Acts" }, { "type": "p", "text": "Opening acts or guests may sometimes tour with headlining performers. We are not always made aware of opening acts or the length of their performances. Opening acts, as well as festival performers, are subject to change or cancellation at any time without notice. No refund will be owed if an opening act or festival performer is changed or canceled." }, { "type": "h2", "text": "Canceled and Rescheduled Events" }, { "type": "p", "text": "Occasionally, events are canceled or postponed. Should this occur, we will attempt to contact you to inform you of refund or exchange procedures for that event. For exact instructions on any canceled or postponed event, please check the event information online or contact help@blocktickets.xyz." }, { "type": "p", "text": "If an event is canceled, and the ticket you purchased through the Site is eligible for a refund, we will issue you a refund to the credit card that you used to purchase that ticket." }, { "type": "p", "text": "If the event was moved or rescheduled, the Event Provider may set refund limitations. Please contact help@blocktickets.xyz for more information or to request a refund if you cannot attend the rescheduled event. Please make sure to include your account number so we can expedite your refund, if applicable." }, { "type": "h2", "text": "Refunds and Exchanges" }, { "type": "p", "text": "Before purchasing tickets, carefully review your event and seat selection. Policies set forth by Event Providers generally prohibit us from issuing exchanges or refunds after a ticket has been purchased, or for lost, stolen, damaged, or destroyed tickets." }, { "type": "p", "text": "You agree that you will not attempt to evade, avoid, or circumvent any refund prohibitions in any manner with regard to tickets you purchased. Without limiting the generality of the foregoing, you will not contact us to seek a refund or exchange when we are prohibited from providing one by our clients, and you will not dispute or otherwise seek a “chargeback” from the company whose credit card you used to purchase tickets from the Site. Should you do so, your tickets may be canceled, and we may, in our sole discretion, refuse to honor pending and future ticket purchases made from all credit card accounts or online accounts on which such chargebacks have been made, and may prohibit all persons in whose name the credit card accounts exist, and any person who accesses any associated online account or credit card or who otherwise breaches this provision, from using the Site." }, { "type": "p", "text": "If we issue you a refund for a ticket due to a canceled or postponed event, we will issue a refund of the ticket’s face value paid (or, for a discounted ticket, the discounted ticket price paid) and, if purchased on Blocktickets.xyz, all service fees. In no event will delivery prices or any other fees or amounts be refunded. If a refund is issued, it will be issued using the same method of payment that was used to purchase the tickets. We will not be liable for travel or any other expenses that you or anyone else incurs in connection with a canceled or postponed event." }, { "type": "h2", "text": "Billing Information Verification" }, { "type": "p", "text": "Orders are processed only after a billing address, and other billing information, has been verified. Occasionally, we receive incorrect billing or credit card account information for a ticket order that can delay processing and delivery. In these cases, Blocktickets customer service will attempt to contact you using the information provided at the time of purchase. If we are unable to reach you after our initial attempt, we may cancel your order and may sell your tickets to another customer without further notice." }, { "type": "h2", "text": "Pricing and Other Errors" }, { "type": "p", "text": "If the amount you pay for a ticket is incorrect — regardless of whether because of an error in a price posted on this Site or otherwise communicated to you — or if you are able to order a ticket before its scheduled on-sale or presale date, or you are able to order a ticket that was not supposed to have been released for sale, then we will have the right to cancel that ticket (or the order for that ticket) and refund to you the amount that you paid. This will apply regardless of whether the error was caused by human error or a transactional malfunction of this Site or another Blocktickets-operated system." }, { "type": "h2", "text": "Multiple Browser Windows" }, { "type": "p", "text": "When ordering tickets online with us, please ensure you are looking for tickets and placing an order using only one browser window. Looking up tickets using multiple browser windows could result in losing your tickets or timer expiration." }, { "type": "h2", "text": "Limitation of Liability" }, { "type": "p", "text": "Balls, pucks, and other objects may fly into the spectator area during an event. Despite spectator shielding, injury can occur. Stay alert at all times before, during, and after play or performance. If struck, immediately ask an usher for directions to a medical station. You voluntarily assume all risks and dangers incidental to the event for which the ticket is issued, whether occurring before, during, or after the event, and you waive any claims for personal injury or death against us, management, facilities, leagues, artists, other participants, and all of our respective parents, affiliated entities, agents, officers, directors, owners, and employees, on behalf of yourself and any accompanying minor. You bear all risks of inclement weather. Event date and time are subject to change. See the Limitation of Liability section in the Terms & Conditions for additional limits on our liability." }, { "type": "h2", "text": "License; Ejection and Cancellation; No Redemption Value" }, { "type": "p", "text": "You agree to comply with all of the Event Provider’s applicable rules, policies, terms, and conditions (“Event Provider Rules”). Event Providers reserve the right, without refund of any amount paid, to refuse admission to, or eject, any person whose conduct management deems disorderly, who uses vulgar or abusive language, or who fails to comply with Event Provider Rules. Breach of these terms or rules will terminate your license to attend the event without refund. A ticket is a revocable license, and admission may be refused upon refunding the ticket’s face amount. A ticket is not redeemable for cash." }, { "type": "h2", "text": "Recording, Transmission, and Exhibition" }, { "type": "p", "text": "You agree that the event for which you purchase tickets is a public event, that your appearance and actions inside and outside the venue where the event occurs are public in nature, and that you have no expectation of privacy with regard to your actions or conduct at the event. You grant permission to us and the Event Provider(s) to utilize your name, image, likeness, acts, poses, plays, appearance, movements, and statements in any live or recorded audio, video, or photographic display or other transmission, exhibition, publication, or reproduction made of, or at, the event (regardless of whether before, during, or after play or performance) for any purpose, in any manner, in any medium or context now known or hereafter developed, without further authorization from, or compensation to, you or anyone acting on your behalf." }, { "type": "h2", "text": "You Are Subject to Search" }, { "type": "p", "text": "You and your belongings may be searched on entry to the event. You consent to such searches and waive any related claims that may arise. If you elect not to consent to such searches, you may be denied entry to the event without refund or other compensation. Under certain facility rules, certain items may not be brought onto the premises, including, without limitation, alcohol, drugs, controlled substances, cameras, recording devices, laser pointers, strobe lights, irritants (e.g., artificial noisemakers), bundles, and containers." }, { "type": "h2", "text": "Unlawful Resale of Tickets; Promotions" }, { "type": "p", "text": "Unlawful resale (or attempted resale), counterfeiting, or copying of tickets is grounds for seizure and cancellation without compensation. Certain maximum resale premiums and restrictions may apply in some states, and we cannot be responsible for providing legal advice regarding the resale or pricing of tickets. You are responsible for complying with all applicable ticket resale laws. We reserve the right to restrict or deny ticket purchasing privileges to anyone that we determine to be, or to have been, in violation of our policies. Because we do not guarantee the authenticity of tickets purchased from any non-authorized third-party reseller (such as brokers or individuals), we recommend that you purchase tickets directly through us, our authorized partners, or the venue box office to ensure ticket authenticity. Tickets may not be used for advertising, promotions, contests, or sweepstakes unless formal written authorization is given by us." }, { "type": "h2", "text": "Contact Us" }, { "type": "p", "text": "If you have any questions about this Purchase Policy, you can contact us:" }, { "type": "li", "text": "By email: help@blocktickets.xyz" } ] }, { "slug": "terms", "title": "Terms & Conditions", "updated": "August 2, 2026", "blocks": [ { "type": "p", "text": "Please read these Terms and Conditions carefully before using Our Service." }, { "type": "h2", "text": "Interpretation and Definitions" }, { "type": "h3", "text": "Interpretation" }, { "type": "p", "text": "The words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural." }, { "type": "h3", "text": "Definitions" }, { "type": "p", "text": "For the purposes of these Terms and Conditions:" }, { "type": "li", "text": "Account means a unique account created for You to access our Service or parts of our Service." }, { "type": "li", "text": "Affiliate means an entity that controls, is controlled by, or is under common control with a party, where “control” means ownership of 50% or more of the shares, equity interest, or other securities entitled to vote for election of directors or other managing authority." }, { "type": "li", "text": "Company (referred to as either “the Company”, “We”, “Us”, or “Our” in this Agreement) refers to Blocktickets Technologies, Inc., 1501 Broadway, Fl 12, New York, NY 10036." }, { "type": "li", "text": "Content refers to content such as text, images, or other information that can be posted, uploaded, linked to, or otherwise made available by You, regardless of the form of that content." }, { "type": "li", "text": "Country refers to: New York, United States." }, { "type": "li", "text": "Device means any device that can access the Service, such as a computer, a cellphone, or a digital tablet." }, { "type": "li", "text": "Feedback means feedback, innovations, or suggestions sent by You regarding the attributes, performance, or features of our Service." }, { "type": "li", "text": "Goods refer to the items offered for sale on the Service." }, { "type": "li", "text": "Orders mean a request by You to purchase Goods from Us." }, { "type": "li", "text": "Promotions refer to contests, sweepstakes, or other promotions offered through the Service." }, { "type": "li", "text": "Service refers to the Website." }, { "type": "li", "text": "Terms and Conditions (also referred to as “Terms”) mean these Terms and Conditions that form the entire agreement between You and the Company regarding the use of the Service." }, { "type": "li", "text": "Third-party Social Media Service means any services or content (including data, information, products, or services) provided by a third party that may be displayed, included, or made available by the Service." }, { "type": "li", "text": "Website refers to Blocktickets, accessible from www.blocktickets.xyz." }, { "type": "li", "text": "You means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable." }, { "type": "h2", "text": "Acknowledgment" }, { "type": "p", "text": "These are the Terms and Conditions governing the use of this Service and the agreement that operates between You and the Company. These Terms and Conditions set out the rights and obligations of all users regarding the use of the Service. Your access to and use of the Service is conditioned on Your acceptance of and compliance with these Terms and Conditions. These Terms and Conditions apply to all visitors, users, and others who access or use the Service. By accessing or using the Service, You agree to be bound by these Terms and Conditions. If You disagree with any part of these Terms and Conditions, then You may not access the Service." }, { "type": "p", "text": "You represent that you are over the age of 18. The Company does not permit those under 18 to use the Service." }, { "type": "p", "text": "Your access to and use of the Service is also conditioned on Your acceptance of and compliance with the Privacy Policy of the Company. Our Privacy Policy describes Our policies and procedures on the collection, use, and disclosure of Your personal information when You use the Application or the Website and tells You about Your privacy rights and how the law protects You. Please read Our Privacy Policy carefully before using Our Service." }, { "type": "h2", "text": "Placing Orders for Goods" }, { "type": "p", "text": "By placing an Order for Goods through the Service, You warrant that You are legally capable of entering into binding contracts." }, { "type": "h3", "text": "Your Information" }, { "type": "p", "text": "If You wish to place an Order for Goods available on the Service, You may be asked to supply certain information relevant to Your Order including, without limitation, Your name, Your email, Your phone number, Your credit card number, the expiration date of Your credit card, Your billing address, and Your shipping information." }, { "type": "p", "text": "You represent and warrant that: (i) You have the legal right to use any credit or debit card(s) or other payment method(s) in connection with any Order; and that (ii) the information You supply to us is true, correct, and complete." }, { "type": "p", "text": "By submitting such information, You grant us the right to provide the information to payment processing third parties for purposes of facilitating the completion of Your Order." }, { "type": "h3", "text": "Order Cancellation" }, { "type": "p", "text": "We reserve the right to refuse or cancel Your Order at any time for certain reasons, including but not limited to:" }, { "type": "li", "text": "Goods availability" }, { "type": "li", "text": "Errors in the description or prices for Goods" }, { "type": "li", "text": "Errors in Your Order" }, { "type": "p", "text": "We reserve the right to refuse or cancel Your Order if fraud or an unauthorized or illegal transaction is suspected." }, { "type": "h3", "text": "Your Order Cancellation Rights" }, { "type": "p", "text": "Any Goods you purchase can only be returned in accordance with these Terms and Conditions and Our Returns Policy. Our Returns Policy forms a part of these Terms and Conditions. Please read our Returns Policy to learn more about your right to cancel Your Order." }, { "type": "p", "text": "Your right to cancel an Order only applies to Goods that are returned in the same condition as You received them. You should also include all of the products’ instructions, documents, and wrappings. Goods that are damaged or not in the same condition as You received them, or which are worn simply beyond opening the original packaging, will not be refunded. You should therefore take reasonable care of the purchased Goods while they are in Your possession. We will reimburse You no later than 14 days from the day on which We receive the returned Goods. We will use the same means of payment as You used for the Order, and You will not incur any fees for such reimbursement." }, { "type": "p", "text": "You will not have any right to cancel an Order for the supply of any of the following Goods:" }, { "type": "li", "text": "The supply of Goods made to Your specifications or clearly personalized." }, { "type": "li", "text": "The supply of Goods which according to their nature are not suitable to be returned, deteriorate rapidly, or where the date of expiry is over." }, { "type": "li", "text": "The supply of Goods which are not suitable for return due to health protection or hygiene reasons and were unsealed after delivery." }, { "type": "li", "text": "The supply of Goods which are, after delivery, according to their nature, inseparably mixed with other items." }, { "type": "li", "text": "The supply of digital content which is not supplied on a tangible medium if the performance has begun with Your prior express consent and You have acknowledged Your loss of cancellation right." }, { "type": "h3", "text": "Availability, Errors, and Inaccuracies" }, { "type": "p", "text": "We are constantly updating Our offerings of Goods on the Service. The Goods available on Our Service may be mispriced, described inaccurately, or unavailable, and We may experience delays in updating information regarding our Goods on the Service and in Our advertising on other websites." }, { "type": "p", "text": "We cannot and do not guarantee the accuracy or completeness of any information, including prices, product images, specifications, availability, and services. We reserve the right to change or update information and to correct errors, inaccuracies, or omissions at any time without prior notice." }, { "type": "h3", "text": "Prices Policy" }, { "type": "p", "text": "The Company reserves the right to revise its prices at any time prior to accepting an Order. The prices quoted may be revised by the Company subsequent to accepting an Order in the event of any occurrence affecting delivery caused by government action, variation in customs duties, increased shipping charges, higher foreign exchange costs, or any other matter beyond the control of the Company. In that event, You will have the right to cancel Your Order." }, { "type": "h3", "text": "Payments" }, { "type": "p", "text": "All Goods purchased are subject to a one-time payment. Payment can be made through various payment methods we have available, such as Visa, Mastercard, Affinity Card, American Express cards, or online payment methods (PayPal, for example). Payment cards (credit cards or debit cards) are subject to validation checks and authorization by Your card issuer. If we do not receive the required authorization, We will not be liable for any delay or non-delivery of Your Order." }, { "type": "h2", "text": "Promotions" }, { "type": "p", "text": "Any Promotions made available through the Service may be governed by rules that are separate from these Terms. If You participate in any Promotions, please review the applicable rules as well as our Privacy Policy. If the rules for a Promotion conflict with these Terms, the Promotion rules will apply." }, { "type": "h2", "text": "User Accounts" }, { "type": "p", "text": "When You create an account with Us, You must provide Us information that is accurate, complete, and current at all times. Failure to do so constitutes a breach of the Terms, which may result in immediate termination of Your account on Our Service." }, { "type": "p", "text": "You are responsible for safeguarding the password that You use to access the Service and for any activities or actions under Your password, whether Your password is with Our Service or a Third-Party Social Media Service. You agree not to disclose Your password to any third party. You must notify Us immediately upon becoming aware of any breach of security or unauthorized use of Your account." }, { "type": "p", "text": "You may not use as a username the name of another person or entity or that is not lawfully available for use, a name or trademark that is subject to any rights of another person or entity other than You without appropriate authorization, or a name that is otherwise offensive, vulgar, or obscene." }, { "type": "h2", "text": "Content" }, { "type": "p", "text": "Our Service allows You to post Content. You are responsible for the Content that You post to the Service, including its legality, reliability, and appropriateness." }, { "type": "p", "text": "By posting Content to the Service, You grant Us the right and license to use, modify, publicly perform, publicly display, reproduce, and distribute such Content on and through the Service. You retain any and all of Your rights to any Content You submit, post, or display on or through the Service, and You are responsible for protecting those rights. You agree that this license includes the right for Us to make Your Content available to other users of the Service, who may also use Your Content subject to these Terms." }, { "type": "p", "text": "You represent and warrant that: (i) the Content is Yours (You own it) or You have the right to use it and grant Us the rights and license as provided in these Terms, and (ii) the posting of Your Content on or through the Service does not violate the privacy rights, publicity rights, copyrights, contract rights, or any other rights of any person." }, { "type": "h3", "text": "Content Restrictions" }, { "type": "p", "text": "The Company is not responsible for the content of the Service’s users. You expressly understand and agree that You are solely responsible for the Content and for all activity that occurs under your account, whether done so by You or any third person using Your account." }, { "type": "p", "text": "You may not transmit any Content that is unlawful, offensive, upsetting, intended to disgust, threatening, libelous, defamatory, obscene, or otherwise objectionable. Examples of such objectionable Content include, but are not limited to, the following:" }, { "type": "li", "text": "Unlawful or promoting unlawful activity." }, { "type": "li", "text": "Defamatory, discriminatory, or mean-spirited content, including references or commentary about religion, race, sexual orientation, gender, national/ethnic origin, or other targeted groups." }, { "type": "li", "text": "Spam, machine- or randomly-generated content, constituting unauthorized or unsolicited advertising, chain letters, any other form of unauthorized solicitation, or any form of lottery or gambling." }, { "type": "li", "text": "Containing or installing any viruses, worms, malware, trojan horses, or other content that is designed or intended to disrupt, damage, or limit the functioning of any software, hardware, or telecommunications equipment, or to damage or obtain unauthorized access to any data or other information of a third person." }, { "type": "li", "text": "Infringing on any proprietary rights of any party, including patent, trademark, trade secret, copyright, right of publicity, or other rights." }, { "type": "li", "text": "Impersonating any person or entity, including the Company and its employees or representatives." }, { "type": "li", "text": "Violating the privacy of any third person." }, { "type": "li", "text": "False information and features." }, { "type": "h3", "text": "Content Backups" }, { "type": "p", "text": "Although regular backups of Content are performed, the Company does not guarantee there will be no loss or corruption of data. Corrupt or invalid backup points may be caused by, without limitation, Content that is corrupted prior to being backed up or that changes during the time a backup is performed." }, { "type": "p", "text": "The Company will provide support and attempt to troubleshoot any known or discovered issues that may affect the backups of Content. But You acknowledge that the Company has no liability related to the integrity of Content or the failure to successfully restore Content to a usable state. You agree to maintain a complete and accurate copy of any Content in a location independent of the Service." }, { "type": "h2", "text": "Copyright Policy" }, { "type": "h3", "text": "Intellectual Property Infringement" }, { "type": "p", "text": "We respect the intellectual property rights of others. It is Our policy to respond to any claim that Content posted on the Service infringes a copyright or other intellectual property rights of any person." }, { "type": "p", "text": "If You are a copyright owner, or authorized on behalf of one, and You believe that a copyrighted work has been copied in a way that constitutes copyright infringement taking place through the Service, You must submit Your notice in writing to the attention of our copyright agent via email at help@blocktickets.xyz and include in Your notice a detailed description of the alleged infringement." }, { "type": "p", "text": "You may be held accountable for damages (including costs and attorneys’ fees) for misrepresenting that any Content is infringing Your copyright." }, { "type": "h3", "text": "DMCA Notice and DMCA Procedure for Copyright Infringement Claims" }, { "type": "p", "text": "You may submit a notification pursuant to the Digital Millennium Copyright Act (DMCA) by providing our Copyright Agent with the following information in writing (see 17 U.S.C. § 512(c)(3) for further detail):" }, { "type": "li", "text": "An electronic or physical signature of the person authorized to act on behalf of the owner of the copyright’s interest." }, { "type": "li", "text": "A description of the copyrighted work that You claim has been infringed, including the URL (i.e., web page address) of the location where the copyrighted work exists or a copy of the copyrighted work." }, { "type": "li", "text": "Identification of the URL or other specific location on the Service where the material that You claim is infringing is located." }, { "type": "li", "text": "Your address, telephone number, and email address." }, { "type": "li", "text": "A statement by You that You have a good faith belief that the disputed use is not authorized by the copyright owner, its agent, or the law." }, { "type": "li", "text": "A statement by You, made under penalty of perjury, that the above information in Your notice is accurate and that You are the copyright owner or authorized to act on the copyright owner’s behalf." }, { "type": "p", "text": "You can contact our copyright agent via email at help@blocktickets.xyz. Upon receipt of a notification, the Company will take whatever action, in its sole discretion, it deems appropriate, including removal of the challenged content from the Service." }, { "type": "h2", "text": "Intellectual Property" }, { "type": "p", "text": "The Service and its original content (excluding Content provided by You or other users), features, and functionality are and will remain the exclusive property of the Company and its licensors. The Service is protected by copyright, trademark, and other laws of both the Country and foreign countries. Our trademarks and trade dress may not be used in connection with any product or service without the prior written consent of the Company." }, { "type": "h2", "text": "Your Feedback to Us" }, { "type": "p", "text": "You assign all rights, title, and interest in any Feedback You provide the Company. If for any reason such assignment is ineffective, You agree to grant the Company a non-exclusive, perpetual, irrevocable, royalty-free, worldwide right and license to use, reproduce, disclose, sub-license, distribute, modify, and exploit such Feedback without restriction." }, { "type": "h2", "text": "Links to Other Websites" }, { "type": "p", "text": "Our Service may contain links to third-party websites or services that are not owned or controlled by the Company." }, { "type": "p", "text": "The Company has no control over, and assumes no responsibility for, the content, privacy policies, or practices of any third-party websites or services. You further acknowledge and agree that the Company shall not be responsible or liable, directly or indirectly, for any damage or loss caused or alleged to be caused by or in connection with the use of or reliance on any such content, goods, or services available on or through any such websites or services." }, { "type": "p", "text": "We strongly advise You to read the terms and conditions and privacy policies of any third-party websites or services that You visit." }, { "type": "h2", "text": "Termination" }, { "type": "p", "text": "We may terminate or suspend Your Account immediately, without prior notice or liability, for any reason whatsoever, including without limitation if You breach these Terms and Conditions. Upon termination, Your right to use the Service will cease immediately. If You wish to terminate Your Account, You may simply discontinue using the Service." }, { "type": "h2", "text": "Limitation of Liability" }, { "type": "p", "text": "Notwithstanding any damages that You might incur, the entire liability of the Company and any of its suppliers under any provision of these Terms, and Your exclusive remedy for all of the foregoing, shall be limited to the amount actually paid by You through the Service or 100 USD if You haven’t purchased anything through the Service." }, { "type": "p", "text": "To the maximum extent permitted by applicable law, in no event shall the Company or its suppliers be liable for any special, incidental, indirect, or consequential damages whatsoever (including, but not limited to, damages for loss of profits, loss of data or other information, business interruption, personal injury, or loss of privacy arising out of or in any way related to the use of or inability to use the Service, third-party software and/or third-party hardware used with the Service, or otherwise in connection with any provision of these Terms), even if the Company or any supplier has been advised of the possibility of such damages and even if the remedy fails of its essential purpose." }, { "type": "p", "text": "Some states do not allow the exclusion of implied warranties or limitation of liability for incidental or consequential damages, which means that some of the above limitations may not apply. In these states, each party’s liability will be limited to the greatest extent permitted by law." }, { "type": "h2", "text": "“AS IS” and “AS AVAILABLE” Disclaimer" }, { "type": "p", "text": "The Service is provided to You “AS IS” and “AS AVAILABLE” and with all faults and defects without warranty of any kind. To the maximum extent permitted under applicable law, the Company, on its own behalf and on behalf of its Affiliates and its and their respective licensors and service providers, expressly disclaims all warranties, whether express, implied, statutory, or otherwise, with respect to the Service, including all implied warranties of merchantability, fitness for a particular purpose, title, and non-infringement, and warranties that may arise out of course of dealing, course of performance, usage, or trade practice. Without limitation to the foregoing, the Company provides no warranty or undertaking, and makes no representation of any kind, that the Service will meet Your requirements, achieve any intended results, be compatible or work with any other software, applications, systems, or services, operate without interruption, meet any performance or reliability standards, or be error-free, or that any errors or defects can or will be corrected." }, { "type": "p", "text": "Without limiting the foregoing, neither the Company nor any of the Company’s providers makes any representation or warranty of any kind, express or implied: (i) as to the operation or availability of the Service, or the information, content, and materials or products included thereon; (ii) that the Service will be uninterrupted or error-free; (iii) as to the accuracy, reliability, or currency of any information or content provided through the Service; or (iv) that the Service, its servers, the content, or emails sent from or on behalf of the Company are free of viruses, scripts, trojan horses, worms, malware, timebombs, or other harmful components." }, { "type": "p", "text": "Some jurisdictions do not allow the exclusion of certain types of warranties or limitations on applicable statutory rights of a consumer, so some or all of the above exclusions and limitations may not apply to You. But in such a case, the exclusions and limitations set forth in this section shall be applied to the greatest extent enforceable under applicable law." }, { "type": "h2", "text": "Governing Law" }, { "type": "p", "text": "The laws of the Country, excluding its conflicts of law rules, shall govern these Terms and Your use of the Service. Your use of the Application may also be subject to other local, state, national, or international laws." }, { "type": "h2", "text": "Disputes Resolution" }, { "type": "p", "text": "If You have any concern or dispute about the Service, You agree to first try to resolve the dispute informally by contacting the Company." }, { "type": "h2", "text": "For European Union (EU) Users" }, { "type": "p", "text": "If You are a European Union consumer, you will benefit from any mandatory provisions of the law of the country in which you are resident." }, { "type": "h2", "text": "United States Legal Compliance" }, { "type": "p", "text": "You represent and warrant that (i) You are not located in a country that is subject to a United States government embargo, or that has been designated by the United States government as a “terrorist supporting” country, and (ii) You are not listed on any United States government list of prohibited or restricted parties." }, { "type": "h2", "text": "Severability and Waiver" }, { "type": "h3", "text": "Severability" }, { "type": "p", "text": "If any provision of these Terms is held to be unenforceable or invalid, such provision will be changed and interpreted to accomplish the objectives of such provision to the greatest extent possible under applicable law, and the remaining provisions will continue in full force and effect." }, { "type": "h3", "text": "Waiver" }, { "type": "p", "text": "Except as provided herein, the failure to exercise a right or to require performance of an obligation under these Terms shall not affect a party’s ability to exercise such right or require such performance at any time thereafter, nor shall the waiver of a breach constitute a waiver of any subsequent breach." }, { "type": "h2", "text": "Translation Interpretation" }, { "type": "p", "text": "These Terms and Conditions may have been translated if We have made them available to You on our Service. You agree that the original English text shall prevail in the case of a dispute." }, { "type": "h2", "text": "Changes to These Terms and Conditions" }, { "type": "p", "text": "We reserve the right, at Our sole discretion, to modify or replace these Terms at any time. If a revision is material, We will make reasonable efforts to provide at least 30 days’ notice prior to any new terms taking effect. What constitutes a material change will be determined at Our sole discretion." }, { "type": "p", "text": "By continuing to access or use Our Service after those revisions become effective, You agree to be bound by the revised terms. If You do not agree to the new terms, in whole or in part, please stop using the website and the Service." }, { "type": "h2", "text": "Contact Us" }, { "type": "p", "text": "If you have any questions about these Terms and Conditions, You can contact us:" }, { "type": "li", "text": "By email: help@blocktickets.xyz" } ] }, { "slug": "privacy", "title": "Privacy Policy", "updated": "August 2, 2026", "blocks": [ { "type": "p", "text": "This Privacy Policy describes Our policies and procedures on the collection, use, and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You. We use Your Personal Data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy." }, { "type": "h2", "text": "Interpretation and Definitions" }, { "type": "h3", "text": "Interpretation" }, { "type": "p", "text": "The words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural." }, { "type": "h3", "text": "Definitions" }, { "type": "p", "text": "For the purposes of this Privacy Policy:" }, { "type": "li", "text": "Account means a unique account created for You to access our Service or parts of our Service." }, { "type": "li", "text": "Business, for the purpose of the CCPA (California Consumer Privacy Act), refers to the Company as the legal entity that collects Consumers’ personal information and determines the purposes and means of the processing of Consumers’ personal information, or on behalf of which such information is collected and that alone, or jointly with others, determines the purposes and means of the processing of Consumers’ personal information, that does business in the State of California." }, { "type": "li", "text": "Company (referred to as either “the Company”, “We”, “Us”, or “Our” in this Agreement) refers to Blocktickets Technologies, Inc., 1501 Broadway, Fl 12, New York, NY 10036." }, { "type": "li", "text": "Consumer, for the purpose of the CCPA (California Consumer Privacy Act), means a natural person who is a California resident. A resident, as defined in the law, includes (1) every individual who is in the USA for other than a temporary or transitory purpose, and (2) every individual who is domiciled in the USA who is outside the USA for a temporary or transitory purpose." }, { "type": "li", "text": "Cookies are small files that are placed on Your computer, mobile device, or any other device by a website, containing the details of Your browsing history on that website among its many uses." }, { "type": "li", "text": "Country refers to: New York, United States." }, { "type": "li", "text": "Data Controller, for the purposes of the GDPR (General Data Protection Regulation), refers to the Company as the legal person which alone or jointly with others determines the purposes and means of the processing of Personal Data." }, { "type": "li", "text": "Device means any device that can access the Service, such as a computer, a cellphone, or a digital tablet." }, { "type": "li", "text": "Do Not Track (DNT) is a concept that has been promoted by US regulatory authorities, in particular the U.S. Federal Trade Commission (FTC), for the Internet industry to develop and implement a mechanism for allowing internet users to control the tracking of their online activities across websites." }, { "type": "li", "text": "Facebook Fan Page is a public profile named Blocktickets specifically created by the Company on the Facebook social network, accessible from https://www.facebook.com/blocktickets.xyz." }, { "type": "li", "text": "Personal Data is any information that relates to an identified or identifiable individual. For the purposes of the GDPR, Personal Data means any information relating to You such as a name, an identification number, location data, online identifier, or one or more factors specific to the physical, physiological, genetic, mental, economic, cultural, or social identity. For the purposes of the CCPA, Personal Data means any information that identifies, relates to, describes, or is capable of being associated with, or could reasonably be linked, directly or indirectly, with You." }, { "type": "li", "text": "Sale, for the purpose of the CCPA (California Consumer Privacy Act), means selling, renting, releasing, disclosing, disseminating, making available, transferring, or otherwise communicating orally, in writing, or by electronic or other means, a Consumer’s personal information to another business or a third party for monetary or other valuable consideration." }, { "type": "li", "text": "Service refers to the Website." }, { "type": "li", "text": "Service Provider means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service, or to assist the Company in analyzing how the Service is used. For the purpose of the GDPR, Service Providers are considered Data Processors." }, { "type": "li", "text": "Third-party Social Media Service refers to any website or any social network website through which a User can log in or create an account to use the Service." }, { "type": "li", "text": "Usage Data refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit)." }, { "type": "li", "text": "Website refers to Blocktickets, accessible from www.blocktickets.xyz." }, { "type": "li", "text": "You means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable. Under the GDPR (General Data Protection Regulation), You can be referred to as the Data Subject or as the User, as you are the individual using the Service." }, { "type": "h2", "text": "Collecting Your Personal Data" }, { "type": "h3", "text": "Types of Data Collected" }, { "type": "p", "text": "Personal Data" }, { "type": "p", "text": "While using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:" }, { "type": "li", "text": "Email address" }, { "type": "li", "text": "First name and last name" }, { "type": "li", "text": "Phone number" }, { "type": "li", "text": "Address, State, Province, ZIP/Postal code, City" }, { "type": "li", "text": "Usage Data" }, { "type": "p", "text": "Usage Data" }, { "type": "p", "text": "Usage Data is collected automatically when using the Service. Usage Data may include information such as Your Device’s Internet Protocol address (e.g., IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers, and other diagnostic data. When You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers, and other diagnostic data. We may also collect information that Your browser sends whenever You visit our Service or when You access the Service by or through a mobile device." }, { "type": "p", "text": "Information from Third-Party Social Media Services" }, { "type": "p", "text": "The Company allows You to create an account and log in to use the Service through the following Third-party Social Media Services:" }, { "type": "li", "text": "Google" }, { "type": "li", "text": "Facebook" }, { "type": "li", "text": "Twitter" }, { "type": "p", "text": "If You decide to register through or otherwise grant us access to a Third-Party Social Media Service, We may collect Personal Data that is already associated with Your Third-Party Social Media Service’s account, such as Your name, Your email address, Your activities, or Your contact list associated with that account. You may also have the option of sharing additional information with the Company through Your Third-Party Social Media Service’s account. If You choose to provide such information and Personal Data, during registration or otherwise, You are giving the Company permission to use, share, and store it in a manner consistent with this Privacy Policy." }, { "type": "p", "text": "Tracking Technologies and Cookies" }, { "type": "p", "text": "We use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies used are beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The technologies We use may include:" }, { "type": "li", "text": "Cookies or Browser Cookies. A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it will refuse Cookies, our Service may use Cookies." }, { "type": "li", "text": "Flash Cookies. Certain features of our Service may use locally stored objects (or Flash Cookies) to collect and store information about Your preferences or Your activity on our Service. Flash Cookies are not managed by the same browser settings as those used for Browser Cookies. For more information on how You can delete Flash Cookies, please read “Where can I change the settings for disabling, or deleting local shared objects?” available at https://helpx.adobe.com/flash-player/kb/disable-local-shared-objects-flash.html." }, { "type": "li", "text": "Web Beacons. Certain sections of our Service and our emails may contain small electronic files known as web beacons (also referred to as clear gifs, pixel tags, and single-pixel gifs) that permit the Company, for example, to count users who have visited those pages or opened an email and for other related website statistics (for example, recording the popularity of a certain section and verifying system and server integrity)." }, { "type": "p", "text": "Cookies can be “Persistent” or “Session” Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. We use both Session and Persistent Cookies for the purposes set out below:" }, { "type": "li", "text": "Necessary / Essential Cookies. Type: Session Cookies. Administered by: Us. Purpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services." }, { "type": "li", "text": "Cookies Policy / Notice Acceptance Cookies. Type: Persistent Cookies. Administered by: Us. Purpose: These Cookies identify if users have accepted the use of cookies on the Website." }, { "type": "li", "text": "Functionality Cookies. Type: Persistent Cookies. Administered by: Us. Purpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website." }, { "type": "li", "text": "Tracking and Performance Cookies. Type: Persistent Cookies. Administered by: Third parties. Purpose: These Cookies are used to track information about traffic to the Website and how users use the Website. The information gathered via these Cookies may directly or indirectly identify you as an individual visitor. This is because the information collected is typically linked to a pseudonymous identifier associated with the device you use to access the Website. We may also use these Cookies to test new pages, features, or new functionality of the Website to see how our users react to them." }, { "type": "p", "text": "For more information about the cookies we use and your choices regarding cookies, please visit our Cookies Policy or the Cookies section of our Privacy Policy." }, { "type": "h2", "text": "Use of Your Personal Data" }, { "type": "p", "text": "The Company may use Personal Data for the following purposes:" }, { "type": "li", "text": "To provide and maintain our Service, including to monitor the usage of our Service." }, { "type": "li", "text": "To manage Your Account: to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities of the Service that are available to You as a registered user." }, { "type": "li", "text": "For the performance of a contract: the development, compliance, and undertaking of the purchase contract for the products, items, or services You have purchased, or of any other contract with Us through the Service." }, { "type": "li", "text": "To contact You: to contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication, such as a mobile application’s push notifications, regarding updates or informative communications related to the functionalities, products, or contracted services, including security updates, when necessary or reasonable for their implementation." }, { "type": "li", "text": "To provide You with news, special offers, and general information about other goods, services, and events which we offer that are similar to those that you have already purchased or enquired about, unless You have opted not to receive such information." }, { "type": "li", "text": "To manage Your requests: to attend and manage Your requests to Us." }, { "type": "li", "text": "To deliver targeted advertising to You: We may use Your information to develop and display content and advertising (and work with third-party vendors who do so) tailored to Your interests and/or location and to measure its effectiveness." }, { "type": "li", "text": "For business transfers: We may use Your information to evaluate or conduct a merger, divestiture, restructuring, reorganization, dissolution, or other sale or transfer of some or all of Our assets, whether as a going concern or as part of bankruptcy, liquidation, or similar proceeding, in which Personal Data held by Us about our Service users is among the assets transferred." }, { "type": "li", "text": "For other purposes: We may use Your information for other purposes, such as data analysis, identifying usage trends, determining the effectiveness of our promotional campaigns, and to evaluate and improve our Service, products, services, marketing, and your experience." }, { "type": "p", "text": "We may share Your personal information in the following situations:" }, { "type": "li", "text": "With Service Providers: We may share Your personal information with Service Providers to monitor and analyze the use of our Service, to advertise on third-party websites to You after You visited our Service, for payment processing, and to contact You." }, { "type": "li", "text": "For business transfers: We may share or transfer Your personal information in connection with, or during negotiations of, any merger, sale of Company assets, financing, or acquisition of all or a portion of Our business to another company." }, { "type": "li", "text": "With Affiliates: We may share Your information with Our affiliates, in which case we will require those affiliates to honor this Privacy Policy. Affiliates include Our parent company and any other subsidiaries, joint venture partners, or other companies that We control or that are under common control with Us." }, { "type": "li", "text": "With business partners: We may share Your information with Our business partners to offer You certain products, services, or promotions." }, { "type": "li", "text": "With other users: when You share personal information or otherwise interact in the public areas with other users, such information may be viewed by all users and may be publicly distributed outside. If You interact with other users or register through a Third-Party Social Media Service, Your contacts on the Third-Party Social Media Service may see Your name, profile, pictures, and description of Your activity. Similarly, other users will be able to view descriptions of Your activity, communicate with You, and view Your profile." }, { "type": "li", "text": "With Your consent: We may disclose Your personal information for any other purpose with Your consent." }, { "type": "h2", "text": "Retention of Your Personal Data" }, { "type": "p", "text": "The Company will retain Your Personal Data only for as long as is necessary for the purposes set out in this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply with our legal obligations (for example, if we are required to retain your data to comply with applicable laws), resolve disputes, and enforce our legal agreements and policies. The Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer time periods." }, { "type": "h2", "text": "Transfer of Your Personal Data" }, { "type": "p", "text": "Your information, including Personal Data, is processed at the Company’s operating offices and in any other places where the parties involved in the processing are located. It means that this information may be transferred to — and maintained on — computers located outside of Your state, province, country, or other governmental jurisdiction where the data protection laws may differ from those of Your jurisdiction. Your consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer. The Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy, and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place, including the security of Your data and other personal information." }, { "type": "h2", "text": "Disclosure of Your Personal Data" }, { "type": "h3", "text": "Business Transactions" }, { "type": "p", "text": "If the Company is involved in a merger, acquisition, or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy." }, { "type": "h3", "text": "Law Enforcement" }, { "type": "p", "text": "Under certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g., a court or a government agency)." }, { "type": "h3", "text": "Other Legal Requirements" }, { "type": "p", "text": "The Company may disclose Your Personal Data in the good faith belief that such action is necessary to:" }, { "type": "li", "text": "Comply with a legal obligation" }, { "type": "li", "text": "Protect and defend the rights or property of the Company" }, { "type": "li", "text": "Prevent or investigate possible wrongdoing in connection with the Service" }, { "type": "li", "text": "Protect the personal safety of Users of the Service or the public" }, { "type": "li", "text": "Protect against legal liability" }, { "type": "h2", "text": "Security of Your Personal Data" }, { "type": "p", "text": "The security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage, is 100% secure. While We strive to use commercially acceptable means to protect Your Personal Data, We cannot guarantee its absolute security." }, { "type": "h2", "text": "Detailed Information on the Processing of Your Personal Data" }, { "type": "p", "text": "The Service Providers We use may have access to Your Personal Data. These third-party vendors collect, store, use, process, and transfer information about Your activity on Our Service in accordance with their Privacy Policies." }, { "type": "h3", "text": "Analytics" }, { "type": "p", "text": "We may use third-party Service Providers to monitor and analyze the use of our Service." }, { "type": "li", "text": "Google Analytics. Google Analytics is a web analytics service offered by Google that tracks and reports website traffic. Google uses the data collected to track and monitor the use of our Service. This data is shared with other Google services. Google may use the collected data to contextualize and personalize the ads of its own advertising network. You can opt out of having your activity on the Service made available to Google Analytics by installing the Google Analytics opt-out browser add-on. The add-on prevents the Google Analytics JavaScript (ga.js, analytics.js, and dc.js) from sharing information with Google Analytics about visit activity. For more information on the privacy practices of Google, please visit the Google Privacy & Terms web page: https://policies.google.com/privacy." }, { "type": "li", "text": "Firebase. Firebase is an analytics service provided by Google Inc. You may opt out of certain Firebase features through your mobile device settings, such as your device advertising settings, or by following the instructions provided by Google in their Privacy Policy: https://policies.google.com/privacy. For more information on what type of information Firebase collects, please visit the “How Google uses data when you use our partners’ sites or apps” webpage: https://policies.google.com/technologies/partner-sites." }, { "type": "li", "text": "Matomo. Matomo is a web analytics service. You can visit their Privacy Policy page here: https://matomo.org/privacy-policy." }, { "type": "li", "text": "Clicky. Clicky is a web analytics service. Read the Privacy Policy for Clicky here: https://clicky.com/terms." }, { "type": "li", "text": "Statcounter. Statcounter is a web traffic analysis tool. You can read the Privacy Policy for Statcounter here: https://statcounter.com/about/legal/." }, { "type": "li", "text": "Flurry Analytics. The Flurry Analytics service is provided by Yahoo! Inc. You can opt out of the Flurry Analytics service to prevent Flurry Analytics from using and sharing your information by visiting Flurry’s opt-out page: https://developer.yahoo.com/flurry/end-user-opt-out/. For more information on the privacy practices and policies of Yahoo!, please visit their Privacy Policy page: https://policies.yahoo.com/xa/en/yahoo/privacy/index.html." }, { "type": "li", "text": "Mixpanel. Mixpanel is provided by Mixpanel Inc. You can prevent Mixpanel from using your information for analytics purposes by opting out. To opt out of the Mixpanel service, please visit this page: https://mixpanel.com/optout/. For more information on what type of information Mixpanel collects, please visit the Terms of Use page of Mixpanel: https://mixpanel.com/legal/terms-of-use/." }, { "type": "li", "text": "Unity Analytics. Unity Analytics is provided by Unity Technologies. Unity Analytics collects, stores, uses, processes, and transfers personal information to provide, operate, and improve Unity Technologies services, including personalized advertising services. For more information on what type of information Unity Technologies collects, or to opt out of Unity Analytics, please visit their Privacy Policy page: https://unity3d.com/legal/privacy-policy. You may opt out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information." }, { "type": "h3", "text": "Email Marketing" }, { "type": "p", "text": "We may use Your Personal Data to contact You with newsletters, marketing or promotional materials, and other information that may be of interest to You. You may opt out of receiving any, or all, of these communications from Us by following the unsubscribe link or instructions provided in any email We send or by contacting Us. We may use Email Marketing Service Providers to manage and send emails to You." }, { "type": "li", "text": "Mailchimp. Mailchimp is an email marketing sending service provided by The Rocket Science Group LLC. For more information on the privacy practices of Mailchimp, please visit their Privacy Policy: https://www.intuit.com/privacy/statement/." }, { "type": "h3", "text": "Payments" }, { "type": "p", "text": "We may provide paid products and/or services within the Service. In that case, we may use third-party services for payment processing (e.g., payment processors). We will not store or collect Your payment card details. That information is provided directly to Our third-party payment processors, whose use of Your personal information is governed by their Privacy Policy. These payment processors adhere to the standards set by PCI-DSS as managed by the PCI Security Standards Council, which is a joint effort of brands like Visa, Mastercard, American Express, and Discover. PCI-DSS requirements help ensure the secure handling of payment information." }, { "type": "li", "text": "Stripe. Their Privacy Policy can be viewed at https://stripe.com/privacy." }, { "type": "h3", "text": "Behavioral Remarketing" }, { "type": "p", "text": "The Company uses remarketing services to advertise to You after You accessed or visited our Service. We and Our third-party vendors use cookies and non-cookie technologies to help Us recognize Your Device and understand how You use our Service so that We can improve our Service to reflect Your interests and serve You advertisements that are likely to be of more interest to You. These third-party vendors collect, store, use, process, and transfer information about Your activity on Our Service in accordance with their Privacy Policies and to enable Us to:" }, { "type": "li", "text": "Measure and analyze traffic and browsing activity on Our Service" }, { "type": "li", "text": "Show advertisements for our products and/or services to You on third-party websites or apps" }, { "type": "li", "text": "Measure and analyze the performance of Our advertising campaigns" }, { "type": "p", "text": "Some of these third-party vendors may use non-cookie technologies that may not be impacted by browser settings that block cookies. Your browser may not permit You to block such technologies. You can use the following third-party tools to decline the collection and use of information for the purpose of serving You interest-based advertising:" }, { "type": "li", "text": "The NAI’s opt-out platform: http://www.networkadvertising.org/choices/" }, { "type": "li", "text": "The EDAA’s opt-out platform: http://www.youronlinechoices.com/" }, { "type": "li", "text": "The DAA’s opt-out platform: http://optout.aboutads.info/?c=2&lang=EN" }, { "type": "p", "text": "You may opt out of all personalized advertising by enabling privacy features on Your mobile device such as Limit Ad Tracking (iOS) and Opt Out of Ads Personalization (Android). See Your mobile device Help system for more information." }, { "type": "p", "text": "We may share information, such as hashed email addresses (if available) or other online identifiers collected on Our Service, with these third-party vendors. This allows Our third-party vendors to recognize and deliver You ads across devices and browsers. To read more about the technologies used by these third-party vendors and their cross-device capabilities, please refer to the Privacy Policy of each vendor listed below." }, { "type": "p", "text": "The third-party vendors We use are:" }, { "type": "li", "text": "Google Ads (AdWords). The Google Ads (AdWords) remarketing service is provided by Google Inc. You can opt out of Google Analytics for Display Advertising and customize the Google Display Network ads by visiting the Google Ads Settings page: http://www.google.com/settings/ads. Google also recommends installing the Google Analytics Opt-out Browser Add-on (https://tools.google.com/dlpage/gaoptout) for your web browser. For more information on the privacy practices of Google, please visit the Google Privacy & Terms web page: https://policies.google.com/privacy." }, { "type": "li", "text": "Twitter. The Twitter remarketing service is provided by Twitter Inc. You can opt out of Twitter’s interest-based ads by following their instructions: https://support.twitter.com/articles/20170405. You can learn more about the privacy practices and policies of Twitter by visiting their Privacy Policy page: https://twitter.com/privacy." }, { "type": "li", "text": "Facebook. The Facebook remarketing service is provided by Facebook Inc. You can learn more about interest-based advertising from Facebook by visiting this page: https://www.facebook.com/help/516147308587266. To opt out of Facebook’s interest-based ads, follow these instructions from Facebook: https://www.facebook.com/help/568137493302217. Facebook adheres to the Self-Regulatory Principles for Online Behavioural Advertising established by the Digital Advertising Alliance. You can also opt out from Facebook and other participating companies through the Digital Advertising Alliance in the USA (http://www.aboutads.info/choices/), the Digital Advertising Alliance of Canada (http://youradchoices.ca/), or the European Interactive Digital Advertising Alliance in Europe (http://www.youronlinechoices.eu/), or opt out using your mobile device settings. For more information on the privacy practices of Facebook, please visit Facebook’s Data Policy: https://www.facebook.com/privacy/explanation." }, { "type": "h2", "text": "CCPA Privacy" }, { "type": "p", "text": "This privacy notice section for California residents supplements the information contained in Our Privacy Policy, and it applies solely to all visitors, users, and others who reside in the State of California." }, { "type": "h3", "text": "Categories of Personal Information Collected" }, { "type": "p", "text": "We collect information that identifies, relates to, describes, references, is capable of being associated with, or could reasonably be linked, directly or indirectly, with a particular Consumer or Device. The following is a list of categories of personal information which we may collect or may have collected from California residents within the last twelve (12) months." }, { "type": "p", "text": "Please note that the categories and examples provided in the list below are those defined in the CCPA. This does not mean that all examples of that category of personal information were in fact collected by Us, but reflects our good faith belief to the best of our knowledge that some of that information from the applicable category may be and may have been collected. For example, certain categories of personal information would only be collected if You provided such personal information directly to Us." }, { "type": "li", "text": "Category A: Identifiers. Examples: A real name, alias, postal address, unique personal identifier, online identifier, Internet Protocol address, email address, account name, driver’s license number, passport number, or other similar identifiers. Collected: Yes." }, { "type": "li", "text": "Category B: Personal information categories listed in the California Customer Records statute (Cal. Civ. Code § 1798.80(e)). Examples: A name, signature, Social Security number, physical characteristics or description, address, telephone number, passport number, driver’s license or state identification card number, insurance policy number, education, employment, employment history, bank account number, credit card number, debit card number, or any other financial information, medical information, or health insurance information. Some personal information included in this category may overlap with other categories. Collected: Yes." }, { "type": "li", "text": "Category C: Protected classification characteristics under California or federal law. Examples: Age (40 years or older), race, color, ancestry, national origin, citizenship, religion or creed, marital status, medical condition, physical or mental disability, sex (including gender, gender identity, gender expression, pregnancy or childbirth and related medical conditions), sexual orientation, veteran or military status, and genetic information (including familial genetic information). Collected: Yes." }, { "type": "li", "text": "Category D: Commercial information. Examples: Records and history of products or services purchased or considered. Collected: Yes." }, { "type": "li", "text": "Category E: Biometric information. Examples: Genetic, physiological, behavioral, and biological characteristics, or activity patterns used to extract a template or other identifier or identifying information, such as fingerprints, faceprints, and voiceprints, iris or retina scans, keystroke, gait, or other physical patterns, and sleep, health, or exercise data. Collected: No." }, { "type": "li", "text": "Category F: Internet or other similar network activity. Examples: Interaction with our Service or advertisement. Collected: Yes." }, { "type": "li", "text": "Category G: Geolocation data. Examples: Approximate physical location. Collected: No." }, { "type": "li", "text": "Category H: Sensory data. Examples: Audio, electronic, visual, thermal, olfactory, or similar information. Collected: No." }, { "type": "li", "text": "Category I: Professional or employment-related information. Examples: Current or past job history or performance evaluations. Collected: No." }, { "type": "li", "text": "Category J: Non-public education information (per the Family Educational Rights and Privacy Act (20 U.S.C. Section 1232g, 34 C.F.R. Part 99)). Examples: Education records directly related to a student maintained by an educational institution or party acting on its behalf, such as grades, transcripts, class lists, student schedules, student identification codes, student financial information, or student disciplinary records. Collected: No." }, { "type": "li", "text": "Category K: Inferences drawn from other personal information. Examples: Profile reflecting a person’s preferences, characteristics, psychological trends, predispositions, behavior, attitudes, intelligence, abilities, and aptitudes. Collected: No." }, { "type": "p", "text": "Under the CCPA, personal information does not include:" }, { "type": "li", "text": "Publicly available information from government records" }, { "type": "li", "text": "Deidentified or aggregated consumer information" }, { "type": "li", "text": "Information excluded from the CCPA’s scope, such as: health or medical information covered by the Health Insurance Portability and Accountability Act of 1996 (HIPAA) and the California Confidentiality of Medical Information Act (CMIA) or clinical trial data; and personal information covered by certain sector-specific privacy laws, including the Fair Credit Reporting Act (FCRA), the Gramm-Leach-Bliley Act (GLBA) or California Financial Information Privacy Act (FIPA), and the Driver’s Privacy Protection Act of 1994" }, { "type": "h3", "text": "Sources of Personal Information" }, { "type": "p", "text": "We obtain the categories of personal information listed above from the following categories of sources:" }, { "type": "li", "text": "Directly from You. For example, from the forms You complete on our Service, preferences You express or provide through our Service, or from Your purchases on our Service." }, { "type": "li", "text": "Indirectly from You. For example, from observing Your activity on our Service." }, { "type": "li", "text": "Automatically from You. For example, through cookies We or our Service Providers set on Your Device as You navigate through our Service." }, { "type": "li", "text": "From Service Providers. For example, third-party vendors to monitor and analyze the use of our Service, third-party vendors to deliver targeted advertising to You, third-party vendors for payment processing, or other third-party vendors that We use to provide the Service to You." }, { "type": "h3", "text": "Use of Personal Information for Business Purposes or Commercial Purposes" }, { "type": "p", "text": "We may use or disclose personal information We collect for “business purposes” or “commercial purposes” (as defined under the CCPA), which may include the following examples:" }, { "type": "li", "text": "To operate our Service and provide You with our Service." }, { "type": "li", "text": "To provide You with support and to respond to Your inquiries, including to investigate and address Your concerns and monitor and improve our Service." }, { "type": "li", "text": "To fulfill or meet the reason You provided the information. For example, if You share Your contact information to ask a question about our Service, We will use that personal information to respond to Your inquiry. If You provide Your personal information to purchase a product or service, We will use that information to process Your payment and facilitate delivery." }, { "type": "li", "text": "To respond to law enforcement requests and as required by applicable law, court order, or governmental regulations." }, { "type": "li", "text": "As described to You when collecting Your personal information or as otherwise set forth in the CCPA." }, { "type": "li", "text": "For internal administrative and auditing purposes." }, { "type": "li", "text": "To detect security incidents and protect against malicious, deceptive, fraudulent, or illegal activity, including, when necessary, to prosecute those responsible for such activities." }, { "type": "p", "text": "Please note that the examples provided above are illustrative and not intended to be exhaustive. For more details on how we use this information, please refer to the “Use of Your Personal Data” section. If We decide to collect additional categories of personal information or use the personal information We collected for materially different, unrelated, or incompatible purposes, We will update this Privacy Policy." }, { "type": "h3", "text": "Disclosure of Personal Information for Business Purposes or Commercial Purposes" }, { "type": "p", "text": "We may use or disclose, and may have used or disclosed in the last twelve (12) months, the following categories of personal information for business or commercial purposes:" }, { "type": "li", "text": "Category A: Identifiers" }, { "type": "li", "text": "Category B: Personal information categories listed in the California Customer Records statute (Cal. Civ. Code § 1798.80(e))" }, { "type": "li", "text": "Category D: Commercial information" }, { "type": "li", "text": "Category F: Internet or other similar network activity" }, { "type": "p", "text": "Please note that the categories listed above are those defined in the CCPA. This does not mean that all examples of that category of personal information were in fact disclosed, but reflects our good faith belief to the best of our knowledge that some of that information from the applicable category may be and may have been disclosed. When We disclose personal information for a business purpose or a commercial purpose, We enter a contract that describes the purpose and requires the recipient to both keep that personal information confidential and not use it for any purpose except performing the contract." }, { "type": "h3", "text": "Sale of Personal Information" }, { "type": "p", "text": "As defined in the CCPA, “sell” and “sale” mean selling, renting, releasing, disclosing, disseminating, making available, transferring, or otherwise communicating orally, in writing, or by electronic or other means, a consumer’s personal information by the business to a third party for valuable consideration. This means that We may have received some kind of benefit in return for sharing personal information, but not necessarily a monetary benefit. Please note that the categories listed below are those defined in the CCPA. This does not mean that all examples of that category of personal information were in fact sold, but reflects our good faith belief to the best of our knowledge that some of that information from the applicable category may be and may have been shared for value in return. We may sell, and may have sold in the last twelve (12) months, the following categories of personal information:" }, { "type": "li", "text": "Category A: Identifiers" }, { "type": "li", "text": "Category B: Personal information categories listed in the California Customer Records statute (Cal. Civ. Code § 1798.80(e))" }, { "type": "li", "text": "Category D: Commercial information" }, { "type": "li", "text": "Category F: Internet or other similar network activity" }, { "type": "h3", "text": "Share of Personal Information" }, { "type": "p", "text": "We may share Your personal information identified in the above categories with the following categories of third parties:" }, { "type": "li", "text": "Service Providers" }, { "type": "li", "text": "Payment processors" }, { "type": "li", "text": "Our affiliates" }, { "type": "li", "text": "Our business partners" }, { "type": "li", "text": "Third-party vendors to whom You or Your agents authorize Us to disclose Your personal information in connection with products or services We provide to You" }, { "type": "h3", "text": "Sale of Personal Information of Minors Under 16 Years of Age" }, { "type": "p", "text": "We do not sell the personal information of Consumers We actually know are less than 16 years of age, unless We receive affirmative authorization (the “right to opt-in”) from either the Consumer who is between 13 and 16 years of age, or the parent or guardian of a Consumer less than 13 years of age. Consumers who opt in to the sale of personal information may opt out of future sales at any time. To exercise the right to opt out, You (or Your authorized representative) may submit a request to Us by contacting Us." }, { "type": "p", "text": "If You have reason to believe that a child under the age of 13 (or 16) has provided Us with personal information, please contact Us with sufficient detail to enable Us to delete that information." }, { "type": "h3", "text": "Your Rights under the CCPA" }, { "type": "p", "text": "The CCPA provides California residents with specific rights regarding their personal information. If You are a resident of California, You have the following rights:" }, { "type": "li", "text": "The right to notice. You have the right to be notified which categories of Personal Data are being collected and the purposes for which the Personal Data is being used." }, { "type": "li", "text": "The right to request. Under the CCPA, You have the right to request that We disclose information to You about Our collection, use, sale, disclosure for business purposes, and sharing of personal information. Once We receive and confirm Your request, We will disclose to You: the categories of personal information We collected about You; the categories of sources for the personal information We collected about You; Our business or commercial purpose for collecting or selling that personal information; the categories of third parties with whom We share that personal information; and the specific pieces of personal information We collected about You. If we sold Your personal information or disclosed Your personal information for a business purpose, We will also disclose to You the categories of personal information sold and the categories of personal information disclosed." }, { "type": "li", "text": "The right to say no to the sale of Personal Data (opt-out). You have the right to direct Us not to sell Your personal information. To submit an opt-out request, please contact Us." }, { "type": "li", "text": "The right to delete Personal Data. You have the right to request the deletion of Your Personal Data, subject to certain exceptions. Once We receive and confirm Your request, We will delete (and direct Our Service Providers to delete) Your personal information from our records, unless an exception applies. We may deny Your deletion request if retaining the information is necessary for Us or Our Service Providers to: complete the transaction for which We collected the personal information, provide a good or service that You requested, take actions reasonably anticipated within the context of our ongoing business relationship with You, or otherwise perform our contract with You; detect security incidents, protect against malicious, deceptive, fraudulent, or illegal activity, or prosecute those responsible for such activities; debug products to identify and repair errors that impair existing intended functionality; exercise free speech, ensure the right of another consumer to exercise their free speech rights, or exercise another right provided for by law; comply with the California Electronic Communications Privacy Act (Cal. Penal Code § 1546 et seq.); engage in public or peer-reviewed scientific, historical, or statistical research in the public interest that adheres to all other applicable ethics and privacy laws, when the information’s deletion may likely render impossible or seriously impair the research’s achievement, if You previously provided informed consent; enable solely internal uses that are reasonably aligned with consumer expectations based on Your relationship with Us; comply with a legal obligation; or make other internal and lawful uses of that information that are compatible with the context in which You provided it." }, { "type": "li", "text": "The right not to be discriminated against. You have the right not to be discriminated against for exercising any of Your consumer rights, including by: denying goods or services to You; charging different prices or rates for goods or services, including the use of discounts or other benefits or imposing penalties; providing a different level or quality of goods or services to You; or suggesting that You will receive a different price or rate for goods or services or a different level or quality of goods or services." }, { "type": "h3", "text": "Exercising Your CCPA Data Protection Rights" }, { "type": "p", "text": "In order to exercise any of Your rights under the CCPA, and if You are a California resident, You can contact Us by email: help@blocktickets.xyz." }, { "type": "p", "text": "Only You, or a person registered with the California Secretary of State that You authorize to act on Your behalf, may make a verifiable request related to Your personal information. Your request to Us must: provide sufficient information that allows Us to reasonably verify You are the person about whom We collected personal information or an authorized representative; and describe Your request with sufficient detail that allows Us to properly understand, evaluate, and respond to it." }, { "type": "p", "text": "We cannot respond to Your request or provide You with the required information if We cannot verify Your identity or authority to make the request and confirm that the personal information relates to You." }, { "type": "p", "text": "We will disclose and deliver the required information free of charge within 45 days of receiving Your verifiable request. The time period to provide the required information may be extended once by an additional 45 days when reasonably necessary and with prior notice." }, { "type": "p", "text": "Any disclosures We provide will only cover the 12-month period preceding the verifiable request’s receipt." }, { "type": "p", "text": "For data portability requests, We will select a format to provide Your personal information that is readily useable and should allow You to transmit the information from one entity to another entity without hindrance." }, { "type": "h3", "text": "Do Not Sell My Personal Information" }, { "type": "p", "text": "You have the right to opt out of the sale of Your personal information. Once We receive and confirm a verifiable consumer request from You, we will stop selling Your personal information. To exercise Your right to opt out, please contact Us. The Service Providers we partner with (for example, our analytics or advertising partners) may use technology on the Service that sells personal information as defined by the CCPA. If you wish to opt out of the use of Your personal information for interest-based advertising purposes and these potential sales as defined under the CCPA, you may do so by following the instructions below." }, { "type": "p", "text": "Please note that any opt-out is specific to the browser You use. You may need to opt out on every browser that You use." }, { "type": "p", "text": "Website" }, { "type": "p", "text": "You can opt out of receiving ads that are personalized as served by our Service Providers by following our instructions presented on the Service:" }, { "type": "li", "text": "The NAI’s opt-out platform: http://www.networkadvertising.org/choices/" }, { "type": "li", "text": "The EDAA’s opt-out platform: http://www.youronlinechoices.com/" }, { "type": "li", "text": "The DAA’s opt-out platform: http://optout.aboutads.info/?c=2&lang=EN" }, { "type": "p", "text": "The opt-out will place a cookie on Your computer that is unique to the browser You use to opt out. If you change browsers or delete the cookies saved by your browser, You will need to opt out again." }, { "type": "p", "text": "Mobile Devices" }, { "type": "p", "text": "Your mobile device may give You the ability to opt out of the use of information about the apps You use in order to serve You ads that are targeted to Your interests:" }, { "type": "li", "text": "“Opt out of Interest-Based Ads” or “Opt out of Ads Personalization” on Android devices" }, { "type": "li", "text": "“Limit Ad Tracking” on iOS devices" }, { "type": "p", "text": "You can also stop the collection of location information from Your mobile device by changing the preferences on Your mobile device." }, { "type": "h2", "text": "“Do Not Track” Policy as Required by the California Online Privacy Protection Act (CalOPPA)" }, { "type": "p", "text": "Our Service does not respond to Do Not Track signals." }, { "type": "p", "text": "However, some third-party websites do keep track of Your browsing activities. If You are visiting such websites, You can set Your preferences in Your web browser to inform websites that You do not want to be tracked. You can enable or disable DNT by visiting the preferences or settings page of Your web browser." }, { "type": "h2", "text": "Children’s Privacy" }, { "type": "p", "text": "The Service may contain content appropriate for children under the age of 13. As a parent, you should know that through the Service, children under the age of 13 may participate in activities that involve the collection or use of personal information. We use reasonable efforts to ensure that before we collect any personal information from a child, the child’s parent receives notice of and consents to our personal information practices." }, { "type": "p", "text": "We also may limit how We collect, use, and store some of the information of Users between 13 and 18 years old. In some cases, this means We will be unable to provide certain functionality of the Service to these Users. If We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent’s consent before We collect and use that information." }, { "type": "p", "text": "We may ask a User to verify their date of birth before collecting any personal information from them. If the User is under the age of 13, the Service will be either blocked or redirected to a parental consent process." }, { "type": "h3", "text": "Information Collected from Children Under the Age of 13" }, { "type": "p", "text": "The Company may collect and store persistent identifiers such as cookies or IP addresses from Children without parental consent for the purpose of supporting the internal operation of the Service." }, { "type": "p", "text": "We may collect and store other personal information about children if this information is submitted by a child with prior parental consent or by the parent or guardian of the child." }, { "type": "p", "text": "The Company may collect and store the following types of personal information about a child when submitted by a child with prior parental consent or by the parent or guardian of the child:" }, { "type": "li", "text": "First and/or last name" }, { "type": "li", "text": "Date of birth" }, { "type": "li", "text": "Gender" }, { "type": "li", "text": "Grade level" }, { "type": "li", "text": "Email address" }, { "type": "li", "text": "Telephone number" }, { "type": "li", "text": "Parent’s or guardian’s name" }, { "type": "li", "text": "Parent’s or guardian’s email address" }, { "type": "p", "text": "For further details on the information We might collect, You can refer to the “Types of Data Collected” section of this Privacy Policy. We follow our standard Privacy Policy for the disclosure of personal information collected from and about children." }, { "type": "h3", "text": "Parental Access" }, { "type": "p", "text": "A parent who has already given the Company permission to collect and use their child’s personal information can, at any time:" }, { "type": "li", "text": "Review, correct, or delete the child’s personal information" }, { "type": "li", "text": "Discontinue further collection or use of the child’s personal information" }, { "type": "p", "text": "To make such a request, You can write to Us using the contact information provided in this Privacy Policy." }, { "type": "h2", "text": "Your California Privacy Rights (California’s Shine the Light Law)" }, { "type": "p", "text": "Under California Civil Code Section 1798 (California’s Shine the Light law), California residents with an established business relationship with us can request information once a year about sharing their Personal Data with third parties for the third parties’ direct marketing purposes." }, { "type": "p", "text": "If you’d like to request more information under the California Shine the Light law, and if You are a California resident, You can contact Us using the contact information provided below." }, { "type": "h2", "text": "California Privacy Rights for Minor Users (California Business and Professions Code Section 22581)" }, { "type": "p", "text": "California Business and Professions Code Section 22581 allows California residents under the age of 18 who are registered users of online sites, services, or applications to request and obtain removal of content or information they have publicly posted." }, { "type": "p", "text": "To request removal of such data, and if You are a California resident, You can contact Us using the contact information provided below, and include the email address associated with Your account." }, { "type": "p", "text": "Be aware that Your request does not guarantee complete or comprehensive removal of content or information posted online and that the law may not permit or require removal in certain circumstances." }, { "type": "h2", "text": "Links to Other Websites" }, { "type": "p", "text": "Our Service may contain links to other websites that are not operated by Us. If You click on a third-party link, You will be directed to that third party’s site. We strongly advise You to review the Privacy Policy of every site You visit." }, { "type": "p", "text": "We have no control over and assume no responsibility for the content, privacy policies, or practices of any third-party sites or services." }, { "type": "h2", "text": "Changes to This Privacy Policy" }, { "type": "p", "text": "We may update Our Privacy Policy from time to time. We will notify You of any changes by posting the new Privacy Policy on this page." }, { "type": "p", "text": "We will let You know via email and/or a prominent notice on Our Service prior to the change becoming effective and update the “Last updated” date at the top of this Privacy Policy." }, { "type": "p", "text": "You are advised to review this Privacy Policy periodically for any changes. Changes to this Privacy Policy are effective when they are posted on this page." }, { "type": "h2", "text": "Contact Us" }, { "type": "p", "text": "If you have any questions about this Privacy Policy, You can contact us:" }, { "type": "li", "text": "By email: help@blocktickets.xyz" } ] }, { "slug": "disclaimer", "title": "Disclaimer", "updated": "August 2, 2026", "blocks": [ { "type": "h2", "text": "Interpretation and Definitions" }, { "type": "h3", "text": "Interpretation" }, { "type": "p", "text": "The words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural." }, { "type": "h3", "text": "Definitions" }, { "type": "p", "text": "For the purposes of this Disclaimer:" }, { "type": "li", "text": "Company (referred to as either “the Company”, “We”, “Us”, or “Our” in this Agreement) refers to Blocktickets Technologies, Inc., 1501 Broadway, Fl 12, New York, NY 10036." }, { "type": "li", "text": "Service refers to the Website." }, { "type": "li", "text": "Website refers to Blocktickets, accessible from www.blocktickets.xyz." }, { "type": "li", "text": "You means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable." }, { "type": "h2", "text": "Disclaimer" }, { "type": "p", "text": "The information contained on the Service is for general information purposes only. The Company assumes no responsibility for errors or omissions in the contents of the Service." }, { "type": "p", "text": "In no event shall the Company be liable for any special, direct, indirect, consequential, or incidental damages or any damages whatsoever, whether in an action of contract, negligence, or other tort, arising out of or in connection with the use of the Service or the contents of the Service. The Company reserves the right to make additions, deletions, or modifications to the contents on the Service at any time without prior notice." }, { "type": "p", "text": "The Company does not warrant that the Service is free of viruses or other harmful components." }, { "type": "h2", "text": "External Links Disclaimer" }, { "type": "p", "text": "The Service may contain links to external websites that are not provided or maintained by, or in any way affiliated with, the Company. Please note that the Company does not guarantee the accuracy, relevance, timeliness, or completeness of any information on these external websites." }, { "type": "h2", "text": "Advertising Disclaimer" }, { "type": "p", "text": "Third-party advertisements and links to third-party websites may also appear while using the Service. The Company does not make any representation as to the accuracy or suitability of any of the information contained in those advertisements or websites, and does not accept any responsibility or liability for the conduct or content of those advertisements and websites and the offerings made by the third parties." }, { "type": "p", "text": "Third-party advertisements and links to other websites where goods or services are advertised are not endorsements or recommendations by the Company of the third-party sites, goods, or services. The Company takes no responsibility for the content of the ads, promises made, or the quality or reliability of the products or services offered in all advertisements." }, { "type": "h2", "text": "Errors and Omissions Disclaimer" }, { "type": "p", "text": "The information given by the Service is for general guidance on matters of interest only. Even though the Company takes every precaution to ensure that the content of the Service is both current and accurate, errors can occur. In addition, given the changing nature of laws, rules, and regulations, there may be delays, omissions, or inaccuracies in the information contained on the Service. The Company is not responsible for any errors or omissions, or for the results obtained from the use of this information." }, { "type": "h2", "text": "Fair Use Disclaimer" }, { "type": "p", "text": "The Company may use copyrighted material which has not always been specifically authorized by the copyright owner. The Company is making such material available for criticism, comment, news reporting, teaching, scholarship, or research." }, { "type": "p", "text": "The Company believes this constitutes a “fair use” of any such copyrighted material as provided for in Section 107 of the United States Copyright Law." }, { "type": "p", "text": "If You wish to use copyrighted material from the Service, You must obtain permission from the copyright owner." }, { "type": "h2", "text": "Views Expressed Disclaimer" }, { "type": "p", "text": "The Service may contain views and opinions which are those of the authors and do not necessarily reflect the official policy or position of any other author, agency, organization, employer, or company, including the Company." }, { "type": "p", "text": "Comments published by users are their sole responsibility, and the users will take full responsibility, liability, and blame for any libel or litigation that results from something written in, or as a direct result of something written in, a comment. The Company is not liable for any comment published by users and reserves the right to delete any comment for any reason whatsoever." }, { "type": "h2", "text": "No Responsibility Disclaimer" }, { "type": "p", "text": "The information on the Service is provided with the understanding that the Company is not herein engaged in rendering legal, accounting, tax, or other professional advice and services. As such, it should not be used as a substitute for consultation with professional accounting, tax, legal, or other competent advisers." }, { "type": "p", "text": "In no event shall the Company or its suppliers be liable for any special, incidental, indirect, or consequential damages whatsoever arising out of or in connection with your access or use, or inability to access or use, the Service." }, { "type": "h2", "text": "“Use at Your Own Risk” Disclaimer" }, { "type": "p", "text": "All information in the Service is provided “as is”, with no guarantee of completeness, accuracy, timeliness, or of the results obtained from the use of this information, and without warranty of any kind, express or implied, including, but not limited to, warranties of performance, merchantability, and fitness for a particular purpose." }, { "type": "p", "text": "The Company will not be liable to You or anyone else for any decision made or action taken in reliance on the information given by the Service, or for any consequential, special, or similar damages, even if advised of the possibility of such damages." }, { "type": "h2", "text": "Contact Us" }, { "type": "p", "text": "If you have any questions about this Disclaimer, You can contact us:" }, { "type": "li", "text": "By email: help@blocktickets.xyz" } ] }, { "slug": "cookies", "title": "Cookies Policy", "updated": "August 2, 2026", "blocks": [ { "type": "p", "text": "This Cookies Policy explains what Cookies are and how We use them. You should read this policy so You can understand what type of cookies We use, the information We collect using Cookies, and how that information is used." }, { "type": "p", "text": "Cookies do not typically contain any information that personally identifies a user, but personal information that we store about You may be linked to the information stored in and obtained from Cookies. For further information on how We use, store, and keep your personal data secure, see our Privacy Policy." }, { "type": "p", "text": "We do not store sensitive personal information, such as mailing addresses, account passwords, etc., in the Cookies We use." }, { "type": "h2", "text": "Interpretation and Definitions" }, { "type": "h3", "text": "Interpretation" }, { "type": "p", "text": "The words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural." }, { "type": "h3", "text": "Definitions" }, { "type": "p", "text": "For the purposes of this Cookies Policy:" }, { "type": "li", "text": "Company (referred to as either “the Company”, “We”, “Us”, or “Our” in this Agreement) refers to Blocktickets Technologies, Inc., 1501 Broadway, Fl 12, New York, NY 10036." }, { "type": "li", "text": "Cookies are small files that are placed on Your computer, mobile device, or any other device by a website, containing the details of Your browsing history on that website among its many uses." }, { "type": "li", "text": "Website refers to Blocktickets, accessible from www.blocktickets.xyz." }, { "type": "li", "text": "You means the individual accessing or using the Website, or the company, or other legal entity on behalf of which such individual is accessing or using the Website, as applicable. Under the GDPR (General Data Protection Regulation), You can be referred to as the Data Subject or as the User, as you are the individual using the Website." }, { "type": "h2", "text": "The Use of Cookies" }, { "type": "h3", "text": "Types of Cookies We Use" }, { "type": "p", "text": "Cookies can be “Persistent” or “Session” Cookies. Persistent Cookies remain on your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close your web browser." }, { "type": "p", "text": "We use both Session and Persistent Cookies for the purposes set out below:" }, { "type": "li", "text": "Necessary / Essential Cookies. Type: Session Cookies. Administered by: Us. Purpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services." }, { "type": "li", "text": "Cookies Policy / Notice Acceptance Cookies. Type: Persistent Cookies. Administered by: Us. Purpose: These Cookies identify if users have accepted the use of cookies on the Website." }, { "type": "li", "text": "Functionality Cookies. Type: Persistent Cookies. Administered by: Us. Purpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website." }, { "type": "li", "text": "Tracking and Performance Cookies. Type: Persistent Cookies. Administered by: Third parties. Purpose: These Cookies are used to track information about traffic to the Website and how users use the Website. The information gathered via these Cookies may directly or indirectly identify you as an individual visitor. This is because the information collected is typically linked to a pseudonymous identifier associated with the device you use to access the Website. We may also use these Cookies to test new pages, features, or new functionality of the Website to see how our users react to them." }, { "type": "li", "text": "Targeting and Advertising Cookies. Type: Persistent Cookies. Administered by: Third parties. Purpose: These Cookies track your browsing habits to enable Us to show advertising which is more likely to be of interest to You. These Cookies use information about your browsing history to group You with other users who have similar interests. Based on that information, and with Our permission, third-party advertisers can place Cookies to enable them to show adverts which We think will be relevant to your interests while You are on third-party websites." }, { "type": "h2", "text": "Your Choices Regarding Cookies" }, { "type": "p", "text": "If You prefer to avoid the use of Cookies on the Website, first You must disable the use of Cookies in your browser and then delete the Cookies saved in your browser associated with this website. You may use this option for preventing the use of Cookies at any time. If You do not accept Our Cookies, You may experience some inconvenience in your use of the Website, and some features may not function properly. If You’d like to delete Cookies or instruct your web browser to delete or refuse Cookies, please visit the help pages of your web browser." }, { "type": "li", "text": "For the Chrome web browser, please visit this page from Google: https://support.google.com/accounts/answer/32050" }, { "type": "li", "text": "For the Internet Explorer web browser, please visit this page from Microsoft: http://support.microsoft.com/kb/278835" }, { "type": "li", "text": "For the Firefox web browser, please visit this page from Mozilla: https://support.mozilla.org/en-US/kb/delete-cookies-remove-info-websites-stored" }, { "type": "li", "text": "For the Safari web browser, please visit this page from Apple: https://support.apple.com/guide/safari/manage-cookies-and-website-data-sfri11471/mac" }, { "type": "p", "text": "For any other web browser, please visit your web browser’s official web pages." }, { "type": "h2", "text": "More Information About Cookies" }, { "type": "p", "text": "You can learn more about cookies here: All About Cookies by TermsFeed." }, { "type": "h2", "text": "Contact Us" }, { "type": "p", "text": "If you have any questions about this Cookies Policy, You can contact us:" }, { "type": "li", "text": "By email: help@blocktickets.xyz" } ] } ];
